package dev.codearena.service;

import dev.codearena.CodeArenaApplication.Settings;
import java.io.InputStream;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Loads the bundled problem set (problems.json, generated by tools/gen-problems.mjs) for any slug not yet in the database. */
@Component
class ProblemSeeder implements ApplicationRunner {
    private static final Logger log = LoggerFactory.getLogger(ProblemSeeder.class);
    private final Store store;
    private final Settings settings;

    ProblemSeeder(Store store, Settings settings) {
        this.store = store;
        this.settings = settings;
    }

    @Override
    public void run(ApplicationArguments args) throws Exception {
        if (!settings.seedProblems()) return;
        int added = 0;
        try (InputStream in = new ClassPathResource("problems.json").getInputStream()) {
            JsonNode all = JsonMapper.builder().build().readTree(in);
            for (JsonNode p : all) {
                if (store.hasProblem(p.path("slug").asString())) continue;
                store.insertProblem(p);
                added++;
            }
        }
        if (added > 0) log.info("Loaded {} problems.", added);
    }
}
